SELECT
    TAX_P_TYPE,
    ROUND(SUM(CARRY_AMT),2) CARRY_AMT,
    MAX(O_CCY)
FROM
    TAX_BOK_BALANCE
WHERE
    BOOKSET_ID = #{booksetId}
    AND HAPPEN_DATE = #{happenDate}
    AND BOOK_DATE = #{bookDate}
    AND VAT_TYPE = #{vatType}
    AND CALC_TYPE = #{calcType}
GROUP BY 
    TAX_P_TYPE

SELECT
    ROUND(SUM(INCOME_HAPPEN_AMT),2) INCOME_HAPPEN_AMT,
    ROUND(SUM(HAPPEN_AMT),2) HAPPEN_AMT
FROM
    TAX_BOK_BALANCE
WHERE
    BOOKSET_ID = #{booksetId}
    AND HAPPEN_DATE = #{happenDate}
    AND BOOK_DATE = #{bookDate}
    AND VAT_TYPE = #{vatType}
    AND TAX_P_TYPE = #{taxPType}
    AND CALC_TYPE = #{calcType}

SELECT
    ROUND(SUM(HAPPEN_AMT),2) AS happenAmt,

    ROUND(
        CASE WHEN
            SUM(HAPPEN_AMT) < 0 
        THEN 0 
        ELSE 
            SUM(HAPPEN_AMT)
        END,2) AS happenAmt2
FROM
    TAX_BOK_BALANCE
WHERE
    BOOKSET_ID = #{booksetId}
    AND HAPPEN_DATE = #{happenDate}
    AND BOOK_DATE = #{bookDate}
    AND VAT_TYPE = #{vatType}
    AND TAX_P_TYPE = #{taxPType}
    AND CALC_TYPE = #{calcType}

SELECT 
    COUPON_SPECIES
FROM FIN_PRODUCT
WHERE
    FINPROD_TYPE = #{type}
    AND FINPROD_ID = #{busiId}

select count(1) from fin_product_add fpa
where fpa.finprod_id =#{busiId}
and fpa.appear_market_id is not null
